DATA2["YM-023"] = dict(confidence=0.58, trigger=NT, prediction_text="方向：己巳生人有贵可就、可入仕途，终局得官而贵级中等。断语：官鬼丙寅木居应临寅月建旺、官鬼丁卯木居二动，官星两现而旺；二爻官动化父母乙巳火，官化文书主名位落实；初爻父母丁巳火动化兄弟乙未土，巳火即本命，父母动主凭据功名发动。世兄弟丁丑土得庚午日火生，承载有力。应期：单位年，窗口在寅卯之年，主坐标卯年——动官卯木逢值之年得职；等级定为州县佐贰至正印之间的中带，不上拔封疆。", basis="tradition: liuyao\nsystems_used: liuyao\n用神官鬼两现取动之卯官。寅建官旺、日午生世土。动化方向：官化父母为名位凭据向；父化兄为耗线只调量级。第八节功量核算（核心）：贵级等级类——清单：月建寅木助官（助成，强）、官动化父（助成，中）、本命巳父动（助成，中）、父化兄耗（压制，弱）、世土泄火（压制，弱）；主线月建旺官，合计助三压二定带为『中等贵级』带中位，断语在带内不拔高。应期三步：尺度年；三路——逢值卯年、逢值寅年（应官值年主起步，舍为得职点）、化神值巳年（父化兄耗不取）；取卯年。门类应期对表：功名类首选动官逢值，取卯点。")
DATA2["YM-024"] = dict(confidence=0.65, trigger=NT, prediction_text="方向：将晴，近一二日即晴。断语：天时占晴以父母为雨、子孙为晴光。子孙己酉金持世，酉金主晴朗之象临身；父母己巳火居上、丁巳火居初动，初父动化官鬼戊寅木，寅木生巳火本主雨云复聚，然午月日卯，巳火动而化寅受日生只主一时云雨、酉金世旺终主晴。应期：单位日，窗口一至二日，主坐标寅日——化神寅木值日、雨线力尽而晴定；当日余晖先见晴意。", basis="tradition: liuyao\nsystems_used: liuyao\n天时章：父雨子晴对读。世子孙酉金申？午建火克金为压、辛卯日卯冲酉为动象主天气转折。动化方向：父化官寅木，木生火为雨线续力一条，不敌世晴与火数已尽。应期三步：尺度日（天时以日）；三路——化神值寅日、逢冲卯日（冲世主转折当日，作先兆舍）、逢值酉日（晴神值日较远，舍）；取寅日。第八节：无量级类断项。门类应期对表：天时类不在对表固定门类内者按三步原序——本例明写对表无天时专条，按三步取点。")
DATA2["YM-025"] = dict(confidence=0.60, trigger=T(False,True,False,"父母（雨象用神）不现、伏于兄弟午火之下，故 reserve_used=true"), prediction_text="方向：明日无雨、晴或多云无雨。断语：占雨以父母为雨象，本卦父母不现、伏于兄弟丙午火之下，伏雨受飞火泄制、不出头；妻财己酉金居应、丙申金居四，财金主晴；世子孙丙辰土晦而不雨。甲寅日寅木冲申金财爻，主明日风动云散。应期：单位日，主坐标明日甲寅日全日无雨（日单位，本题即问明日）。", basis="tradition: liuyao\nsystems_used: liuyao\n用神父母伏藏（reserve_used）：伏于午火下之子水，申月金生水本可待出，然明日寅日冲申、合？寅申冲动财不助父出，且飞神午火临月建旺泄伏神。静卦旅六合主天气胶着多云。应期三步：尺度日（本题明问明日，日档理由即题面尺度）；三路——伏神值子日（非明日，舍）、冲飞寅日（明日冲申散云，取为无雨坐标）、填实无空；取寅日即明日。第八节：无量级类断项。")
DATA2["YM-027"] = dict(confidence=0.55, trigger=NT, prediction_text="方向：晴在午日，秋成中等偏歉、约七八分收成。断语：占晴兼秋成。父母丙午火居二动、辛巳火居五，晴雨之父星旺于午月；三爻子孙丙申金世动化父母戊午火，子孙化父主云雨化晴光又主禾稼（子孙为禾）化火受耗。甲申日申金冲？申值子孙。应期：单位日，窗口数日内，主坐标午日——父母午火逢值、晴定。秋成量级：子孙申金得申日值、申月将至而旺，然动化午火回克，收成打折至七八分。", basis="tradition: liuyao\nsystems_used: liuyao\n天时父星午火旺动主先雨后晴之转，世子孙动化父为转晴线兼禾稼线。第八节功量核算：秋成数量类——清单：子孙申金值日（助成，中）、化午火回克（压制，中）、父火旺主晴利于晒收（助成，弱）；主线子孙值日与回克相抵，定带为『中带偏下』，断七八分在带内。应期三步：尺度日；三路——逢值午日、化神值午日同点互证、逢值申日（子孙值主禾情非晴点，舍）；取午日。门类应期对表：天时类无专条（明写），按三步原序。")
DATA2["YM-028"] = dict(confidence=0.55, trigger=NT, prediction_text="方向：为父母觅地可得，但迟得、须待未戌土气逢值之期。断语：静卦天地否六合。父母壬戌土居应、乙未土居初，父母为茔地，两现而土气全；世妻财乙卯木克父母，地难速得、费周折与价钱之争；丁未日未土临值父母，地已有眉目在未土一线。官鬼午巳火两现生父母土为助。应期：单位月，窗口在未月或戌月，主坐标未日——父母未土逢值（日辰已示），得地签约落定。", basis="tradition: liuyao\nsystems_used: liuyao\n用神父母（茔地）两现静而得日未值其一。寅建木旺克土为迟因，日未、官火生土为助线。第八节：迟速非量级；得地成否——助成线：父两现、日值、官生父；压制线：世财克父、寅月克土；定带为『可得而迟』带。应期三步：尺度月；三路——逢值未日、逢值戌日（应父值，主另一候选地，舍）、逢合午日（官合？午未合主议价，舍）；取未日。门类应期对表：茔葬类不在对表内，明写对表无此门类，按三步原序。对象复核：承受对象为父母之茔地，应验落于地本身。")
DATA2["YM-029"] = dict(confidence=0.50, trigger=T(False,True,False,"父母（地之用神）不现、伏藏，故 reserve_used=true"), prediction_text="方向：此地可用，但就地迟、须候父母土星出伏逢值方能正式营葬。断语：静卦山天大畜。父母不现、伏于兄弟丙戌土之下（戌土即地气所在，伏而得所）；世官鬼甲寅木、应妻财丙子水，戌月土旺、癸丑日丑土助戌，地气在秋土旺时最实。子水财爻月克主价钱未谐为迟因。应期：单位月，窗口至戌丑土旺之月，主坐标戌日——伏父飞神戌土逢值，定地就葬。可用与迟用两层并断，终局为可用。", basis="tradition: liuyao\nsystems_used: liuyao\n用神父母伏于兄戌土下（reserve_used），飞神即土、伏得飞所载不为全藏。世官寅木戌月合戌主与地有合意。第八节：助成线：飞土旺月、世合地支；压制线：财子月克主价绊、伏神不出；定带『可用而迟』。应期三步：尺度月；三路——飞神值戌日、伏神出值（父为戌未土同路）、逢合寅戌合日（主议定，舍为就葬点）；取戌日。门类应期对表：茔葬无专条，明写对表无此门类。")
DATA2["YM-030"] = dict(confidence=0.58, trigger=T(True,False,False,"初读官鬼初动冲子孙主胎不安欲凶，复核化妻财寅木合亥救胎后主断翻为可安，故 changed_main=true"), prediction_text="方向：胎有惊动而终可安，不至堕失。断语：子孙丁亥水居四，申月金生水、日辰辛亥水临值，胎元得月日生扶本固；初爻官鬼丁巳火动冲亥水，主一时动胎惊扰（腹痛见红一类虚惊）；然官动化妻财戊寅木，寅亥合——化神合住子孙，冲被合解，惊后归安。应期：单位日，窗口旬内，主坐标亥日——子孙逢值、胎安落定；巳日余波只主惊扰过程。", basis="tradition: liuyao\nsystems_used: liuyao\n用神子孙亥水（胎）。父母未丑土两现克水为压，官动冲胎为发动，化寅合亥为救应主线。动化定性：官化财合用神，反转触发即寅亥合，已指认，故主断由惊险翻安。对象复核：承受与应验同为孕妇之胎。应期三步：尺度日；三路——逢值亥日、逢合寅日（化神值主合解过程，舍为安定期点）、冲动巳日（主惊扰，舍）；取亥日。第八节：安否等级——助成线：月生日值、化合救；压制线：官冲、土克；定带『惊而可安』带。门类应期对表：胎产类首选逢合/逢值，候选内亥点兼值取之。")
DATA2["YM-032"] = dict(confidence=0.50, trigger=T(False,True,False,"子孙（胎儿用神）不现、伏藏，性别断语据伏神阴阳落笔，故 reserve_used=true"), prediction_text="方向：所怀为男胎，且可育成。断语：静卦雷泽归妹。子孙不现、伏于妻财丁卯木之下，伏神为申金——金为阳支子孙（申金阳），主男象；戌月土生金、日辰戊辰土生金，伏子得月日土生，育成有气。世父母丁丑土为母体，官鬼午巳火两现生世土，母体承载安稳。应期：单位月，以产期为程，主坐标申月/申日一线子孙出伏逢值时性别与育成见实——本断以男而可育为终局。", basis="tradition: liuyao\nsystems_used: liuyao\n用神子孙伏藏（reserve_used）：伏申金于财卯下，飞木泄金为弱点，月日两土生金为救。性别取伏神支之阴阳（申阳主男），此为本体系胎产章取法，分歧（子孙阴阳二读）已自知、只取伏神一读落断。第八节：无量级类断项；育成等级由生扶两线定『可育』带。应期三步：尺度月（孕程）；三路——出伏逢值申、冲飞寅（寅冲申主发动非育成点，舍）、填实无空；取申为坐标。门类应期对表：胎产类首选子孙逢值，取申点。")
DATA2["YM-033"] = dict(confidence=0.60, trigger=NT, prediction_text="方向：复卜后嗣可得、有子。断语：静卦泽地萃。子孙丁亥水居四，甲申日申金生亥水、卯月木泄而日生有救，子星得日生为有嗣之凭；应兄弟丁酉金生子孙，兄金为原神临应生子；世官鬼乙巳火不克子（火克金不克水）。与初占无子之旧象不同：此卦子星由绝处得生，主行善后嗣缘转至。应期：单位年，窗口一二年内，主坐标亥年——子孙亥水逢值之年得子（或亥月受孕、顺推产期）。", basis="tradition: liuyao\nsystems_used: liuyao\n用神子孙亥水静而得日生，月卯泄为唯一压线。原神兄酉金静生子。卡面事实（通则e）：求测者初占无子后行善自励、复卜——事实面嗣缘转机与卦面子星得生同向，两路互证增强置信。第八节：助成线：日生子、兄生子两条；压制线：月泄一条弱；按估低防线定带不低于中位，断有子足级。应期三步：尺度年（求嗣以年）；三路——逢值亥年、原神值酉年（主缘起，舍为得子点）、逢合寅年（寅亥合主受孕， close 舍取亥为产/得子主点）；取亥年。门类应期对表：胎产/求嗣类首选子孙逢值，取亥点。")
DATA2["YM-034"] = dict(confidence=0.58, trigger=NT, prediction_text="方向：痘将发，发而可愈。断语：占有花以子孙为孩童、官鬼为痘病。子孙壬申金持世，丑月土生金、日乙卯木财耗而金根在月；二爻官鬼丁卯木应动化兄弟己丑土，鬼动主痘毒发动、化丑入墓主毒有收束；三爻兄弟丁丑土动化妻财己亥水，丑土动而晦火（父母午巳为热毒，土晦之）。应期：单位日，窗口三五日内，主坐标申日——子孙逢值、痘点透发见形；透发后转愈。近段发热出痘，远段丑土收毒而安，两段合终局可愈。", basis="tradition: liuyao\nsystems_used: liuyao\n痘疹章：鬼动为发、子旺为身强可托。父母午火居五、巳火居初为热象静而不动。动化方向：鬼化墓为毒收向；兄化财为耗线只调发程量级。对象复核：承受与应验同为该孩童。应期三步：尺度日；三路——逢值申日、鬼值卯日（日辰已临主当日有兆，舍为透发点）、化墓值丑日（主收束作远段点，舍）；取申日。第八节：发痘量级——助成（身强）线月生子孙；压制线鬼动；定带『发而可愈、中等痘情』带。门类应期对表：疾病类首选用神逢值，取申点。")
DATA2["YM-035"] = dict(compidence:=0.60) if False else dict(confidence=0.60, trigger=NT, prediction_text="方向：此童痘亦将发，发势较顺、可愈。断语：与前例同日同问而卦别：子孙壬申金持世且独动，丑月生金、申金旺而自动，子孙发动主痘由内透外、透发为顺；动化兄弟己未土回头生金，身根更固。官鬼丁卯木应静，毒不主动深攻。应期：单位日，窗口二三日内，主坐标申日——子孙动而逢值，痘点见形；较同日他例发更速、势更轻。", basis="tradition: liuyao\nsystems_used: liuyao\n用神子孙申金世独动化土回生，为透发顺象主线（动化方向定性：化回头生）。官鬼静、父母火静，毒与热皆不发动。对象复核：承受与应验同为此另一孩童，不与同日他例相混。应期三步：尺度日；三路——逢值申日、动爻本值申同点互证、化神值未日（主回生收束，舍）；取申日。第八节：痘情量级——助成线：月生、化回生两条；压制线：无动鬼；定带『轻而顺发』带，按估低防线不下调。门类应期对表：疾病类首选用神逢值取申。")
DATA2["YM-037"] = dict(confidence=0.50, trigger=T(False,False,True,"父母金动克子与官动化水生子两线对冲、终局取舍属争议格局，故 disputed=true"), prediction_text="方向：子痘先险后安，终局可保、险中得愈。断语：子孙庚寅木持世，未月土旺、甲辰日辰土耗木，子星休囚；四爻父母戊申金动克寅木子孙，为痘毒伤身之险线；三爻官鬼庚辰土动化兄弟己亥水，亥水回生寅木子孙，为救线。两线对冲：近段申金克木日最险，远段亥水生木转安。应期：单位日，窗口旬内，主坐标亥日——化神亥水逢值、生扶子孙，险情解除；终局单一向愈（通则l），不以先险作凶终局。", basis="tradition: liuyao\nsystems_used: liuyao\n用神子孙寅木世。父母申金动克子（忌线）与官化亥水生子（救线）并存（disputed 留痕）：取舍以动化救线有化神实体、克线申金在未月受土生而辰日？申金动逢辰土生本强——故只断先险后安不断径直顺愈，置信降至 0.50。对象复核（病占复述）：主语为占者之子。应期三步：尺度日；三路——逢值亥日、克神值申日（主险期作近段坐标，舍为终局点）、子值寅日（月日未至且受克，舍）；取亥日。第八节：病势量级——压制线：父金动克、子囚；助成线：化水生子；定带『险而可愈』带。门类应期对表：病类首选化神逢值救点，取亥。")
DATA2["YM-038"] = dict(confidence=0.55, trigger=NT, prediction_text="方向：子病可愈，终局向安。断语：静卦天火同人。子孙壬戌土居应，戌月建临之、日辰甲辰土又冲戌——子星月旺而被日冲为暗动，主药力与转机发动；官鬼己亥水持世为病，亥水在戌月囚、辰日土克，鬼衰无力。父母己卯木居初，甲辰旬空寅卯，父母空主文书/医嘱迟滞，只调迟速。应期：单位日，窗口旬内，主坐标戌日——子孙逢值、冲实同功，病退见安。己亥生人之亥为世鬼值年之说不取，以子星为纲。", basis="tradition: liuyao\nsystems_used: liuyao\n用神子孙戌土（子兼药）月旺日冲暗动；官鬼亥水世衰受日克。病占对象复述：主语为占者之子（己亥生）。应期三步：尺度日；三路——逢值戌日、日冲暗动辰日（当日主发动兆，舍为转机点）、填实卯日（父母空填主医至，舍）；取戌日。动静定性：静卦以月日对用神之冲值定转机，无动化反转。第八节：病势量级——助成线：子月旺、鬼日克两条；压制线：鬼临世一条；定带『可愈、中等病势』带。门类应期对表：病类首选逢值，取戌点。")
DATA2["YM-039"] = dict(confidence=0.60, trigger=NT, prediction_text="方向：妻病偏凶，难愈之险大。断语：病者为程良玉之妻。妻财己酉金居四，卯月建冲酉、财爻月破；壬子日水泄金气，财用神破而泄。子孙己未土、己丑土两现为药，卯月木克土、药爻休囚无力生破财。官鬼己亥水居应，病在对方爻位旺于子日（水日助鬼）。世兄弟己巳火克金又耗。应期：单位日，窗口旬内，主坐标酉日——财爻逢值而值即月破之极，危重见分晓；终局单一向凶。", basis="tradition: liuyao\nsystems_used: liuyao\n用神妻财酉金月破为闸门，无动爻无化神开释，破象贯穿。病占对象复述：主语为占者之妻。原神子孙土囚、忌神兄火临世。应期三步：尺度日；三路——逢值酉日、冲实卯日（月已呈破）、填实无空（父母卯木空为旁线不取）；取酉日危点。第八节：病势等级——压制线：月破、日泄、药囚、鬼得日助四线；助成线：无强线；定带『危重』带足级不断轻。门类应期对表：病类闸门（月破）优先于对表，破无开释故取逢值危点，已写明。")
DATA2["YM-040"] = dict(confidence=0.58, trigger=T(True,False,False,"初读月土克世鬼主凶，复核上爻动化官鬼子水助世与兄动化财生鬼后主断翻安，故 changed_main=true"), prediction_text="方向：夫病可愈，终局向安。断语：病者为占者之夫，官鬼己亥水持世为夫兼病，未月土克亥、日壬寅木泄亥，本主衰象；然上爻子孙壬戌土动化官鬼戊子水，化出子水助亥世鬼之身（子水为亥之帝旺同气），四爻兄弟壬午火动化妻财戊申金，申金生亥水——两动终归生扶世爻亥水，夫身得救应。应期：单位日，窗口旬内，主坐标子日——化神子水逢值，生扶落实、病退。近段寅未之克只主缠绵。", basis="tradition: liuyao\nsystems_used: liuyao\n用神官鬼亥水世（夫病以官为夫）。动化定性：两动化线皆归生扶世爻，反转触发即上动化子水同气助世，已指认，故 changed_main。忌神土（子孙戌为土动却化水解其克性）。病占对象复述：主语为占者之夫。应期三步：尺度日；三路——化神值子日、逢值亥日（世本值次之，舍因化神更主救应落实）、逢合寅日（日已过主当时合绊，舍）；取子日。第八节：病势量级——助成线：化子助、化财生两条；压制线：月克日泄两条；主线取化出助线（发动居首），定带『缠绵可愈』带。门类应期对表：病类首选化神逢值，取子点。")
DATA2["YM-042"] = dict(confidence=0.52, trigger=T(False,True,False,"妻财（妻之用神）不现、伏于初爻子孙卯木之下，故 reserve_used=true"), prediction_text="方向：妻病缠绵而可愈，终局向安、愈期迟。断语：病者为占者之妻。妻财不现、伏于初爻子孙己卯木之下——子孙为药，财伏药下主病得医而藏；戊寅日寅木值伏神飞处，卯木伏神得寅日引动之气（寅卯木气连枝），午月木休而有日助。世兄弟己亥水、官鬼丑戌土两现克亥？官土克世水主病压占者心神，非克财。应期：单位月，窗口在本月内，主坐标卯日——伏财本支逢值出头，妻病见愈。", basis="tradition: liuyao\nsystems_used: liuyao\n用神妻财伏藏（reserve_used）：伏于子孙卯木下，飞神为药不克财反主庇护，伏神得日寅木同气引助可出。静卦既济主事有定向、缠绵成局。病占对象复述：主语为占者之妻。应期三步：尺度月（缠绵病以月内日点）；三路——逢值卯日、冲飞酉日（冲药神反伤庇护，舍）、填实无空；取卯日。第八节：病势量级——助成线：伏得药庇、日引；压制线：伏藏不出、官土两现；定带『缠绵可愈』带。门类应期对表：病类首选伏神逢值，取卯点。")
DATA2["YM-043"] = dict(confidence=0.58, trigger=NT, prediction_text="方向：父病偏凶，近强远衰、难愈之险大。断语：病者为占者之父。父母丙午火居二动为用神，戌月火入墓库之月而午火得戌合、尚有余焰；戊申日申金财爻耗火。父母动化妻财辛亥水回头克——用神动而化克，近段余焰撑持，远段亥水值时回克落实、病转危殆。世官鬼丙寅木生父母火为占者扶持线，只延不救。应期：单位日，窗口旬内，主坐标亥日——化神亥水逢值回克用神，为危期；终局单一向凶。", basis="tradition: liuyao\nsystems_used: liuyao\n用神父母午火动（父病以父母为用，兼原神官木世生之）。动化定性：父化财水回头克为凶向主线；反转条件（化神受制）无——亥水申日得金生反旺。病占对象复述：主语为占者之父。应期三步：尺度日；三路——化神值亥日、逢值午日（主近段撑持作过程点，舍为终局点）、逢合戌日（月合主绊，舍）；取亥日。第八节：病势等级——助成线：世木生父、月合火两线皆延时性质；压制线：化回克、日财耗；主线动化回克（发动居首），定带『重而难愈』带。门类应期对表：病类首选动化化神逢值，取亥点。")

